mapper.select:
SELECT DISTINCT u.id, u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email,u.be_super, u.user_tag,u.point_tag,u.create_time,u.user_mobile,u.create_user_cn_name, CONCAT(GROUP_CONCAT(DISTINCT r.role_name)) AS userRoles, CONCAT(GROUP_CONCAT(DISTINCT r.id)) AS userRoleIds, u.expire_time, u.create_time, u.state, u.avatar, u.note, g.group_name FROM sys_tenant_user AS u LEFT JOIN sys_tenant_user_role AS ur ON u.id = ur.user_id LEFT JOIN sys_tenant_role AS r ON ur.role_id = r.id left join sys_tenant_user_group ug on ug.user_id = u.id left join sys_tenant_group g on g.id = ug.group_id
u.tenant_id = #{tenantId,jdbcType=CHAR}
AND u.user_no LIKE CONCAT('%',#{userNo,jdbcType=CHAR},'%')
AND u.user_real_cn_name LIKE CONCAT('%',#{userRealCnName,jdbcType=CHAR},'%')
AND u.user_email LIKE CONCAT('%',#{userEmail,jdbcType=CHAR},'%')
AND u.state = #{state,jdbcType=CHAR}
AND ur.role_id = #{roleId,jdbcType=CHAR}
AND FIND_IN_SET(#{item}, u.user_tag)
AND ug.group_id like CONCAT(#{groupId,jdbcType=CHAR},'%')
GROUP BY u.id, u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email, u.user_mobile, u.be_super, u.expire_time, u.state, u.avatar, u.note, u.create_user_cn_name, g.group_name ORDER BY u.user_no desc LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

SELECT COUNT(DISTINCT(u.user_no)) FROM sys_tenant_user AS u LEFT JOIN sys_tenant_user_role AS ur ON u.id = ur.user_id LEFT JOIN sys_tenant_role AS r ON ur.role_id = r.id left join sys_tenant_user_group ug on ug.user_id = u.id
u.tenant_id = #{tenantId,jdbcType=CHAR}
AND u.user_no LIKE CONCAT('%',#{userNo,jdbcType=CHAR},'%')
AND u.user_real_cn_name LIKE CONCAT('%',#{userRealCnName,jdbcType=CHAR},'%')
AND u.user_email LIKE CONCAT('%',#{userEmail,jdbcType=CHAR},'%')
AND u.state = #{state,jdbcType=CHAR}
AND ur.role_id = #{roleId,jdbcType=CHAR}
AND FIND_IN_SET(#{item}, u.user_tag)
AND ug.group_id like CONCAT(#{groupId,jdbcType=CHAR},'%')

SELECT DISTINCT ug.id as ug_id, u.id , u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email, u.user_tag, p.id as position_id, CONCAT(GROUP_CONCAT(DISTINCT r.role_name)) AS userRoles, CONCAT(GROUP_CONCAT(DISTINCT r.id)) AS userRoleIds, p.post_name, u.expire_time, u.create_time, u.state, u.avatar, u.note FROM sys_tenant_user_group ug LEFT JOIN sys_tenant_user u ON u.id = ug.user_id LEFT JOIN sys_tenant_user_position up ON u.id = up.user_id AND up.group_id = ug.group_id LEFT JOIN sys_tenant_position p ON up.position_id = p.id LEFT JOIN sys_tenant_user_role AS ur ON u.id = ur.user_id AND ur.org_id = #{groupId,jdbcType=CHAR} LEFT JOIN sys_tenant_role AS r ON ur.role_id = r.id
ug.group_id = #{groupId,jdbcType=CHAR} and u.tenant_id = #{tenantId,jdbcType=CHAR}
GROUP BY ug.id, u.id , u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email, u.user_mobile,u.user_tag, p.id, p.post_name, u.expire_time, u.create_time, u.state, u.avatar, u.note ORDER BY u.user_no desc LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}
